method below_zero(operations: seq<int>) returns (result: bool)
    requires |operations| > 0 // The operations list should not be empty
    ensures result == (exists i :: 0 <= i < |operations| && (|operations| - 1 - i) <= 0)
{
    var balance := 0;
    var i := 0;

    while i < |operations|
        invariant 0 <= i <= |operations|
        invariant balance == Sum(operations[0..i])
    {
        balance := balance + operations[i];
        if balance < 0 {
            return true;
        }
        i := i + 1;
    }

    return false;
}
```

